# Four training rows; each has two input coordinates.
data = [-2, -4; -1, -2; 1, 2; 2, 4];
# 2 inputs -> 1 code -> 2 reconstructed coordinates.
encoder = [1; 0]; decoder = [[1, 1]];
rate = 0.04; steps = 40;
probe = [[3, 6]]; # held out: never used to calculate a gradient
reconstruct() = data * encoder * decoder;
loss() = mean((reconstruct() - data).^2);
before = reconstruct();
{initialMSE: loss(), initialReconstruction: before}
# Chain rule, averaged over every row and coordinate.
gradientEncoder() = 2 / prod(size(data)) * transpose(data) * (reconstruct() - data) * transpose(decoder);
gradientDecoder() = 2 / prod(size(data)) * transpose(data * encoder) * (reconstruct() - data);
{encoderGradient: gradientEncoder(), decoderGradient: gradientDecoder()}
history = zeros(steps + 1); history[1] = loss();
# Each call calculates BOTH gradients before changing either set of weights.
# The object records those steps in order; map repeats this learning cycle.
step(k) = {
  gEncoder: (gEncoder = gradientEncoder()),
  gDecoder: (gDecoder = gradientDecoder()),
  encoder: (encoder = encoder - rate * gEncoder),
  decoder: (decoder = decoder - rate * gDecoder),
  MSE: (history[k + 1] = loss())
};
map(1:steps, step);
{updates: steps, trainedMSE: round(loss(), 12), encoder: round(encoder, 6), decoder: round(decoder, 6)}
{heldOutInput: probe, code: round(probe * encoder, 6), reconstruction: round(probe * encoder * decoder, 6)}
